import java.io.InputStream;
import java.io.IOException;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public long nextLong() {
            int b = readByte();
            while (b != -1 && b <= ' ') {
                b = readByte();
            }
            if (b == -1) return -1;
            long val = 0;
            while (b >= '0' && b <= '9') {
                val = val * 10 + (b - '0');
                b = readByte();
            }
            return val;
        }

        public int nextInt() {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        if (n <= 0) {
            System.out.println(0);
            return;
        }

        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = scanner.nextLong();
        }

        int left = 0;
        int right = n - 1;
        long sumLeft = a[left];
        long sumRight = a[right];
        int operations = 0;

        while (left < right) {
            if (sumLeft == sumRight) {
                left++;
                right--;
                sumLeft = a[left];
                sumRight = a[right];
            } else if (sumLeft < sumRight) {
                left++;
                sumLeft += a[left];
                operations++;
            } else {
                right--;
                sumRight += a[right];
                operations++;
            }
        }

        System.out.println(operations);
    }
}
